(function(){const popup=document.querySelector(".bb-ask-popup:not(.bb-signup-popup)");if(!popup||typeof popup.showModal!=="function"){return;}
const title=popup.querySelector(".bb-intro__title");const choose=popup.querySelector('select[name="instructor"]');let opener=null;const form=popup.querySelector("form");if(form&&choose){const restoreAddress=()=>{if(!popup.open||!opener)return;const name=opener.dataset.bbAsk||"";const option=Array.from(choose.options).find((item)=>item.value===name);choose.value=option?option.value:choose.options[0].value;choose.dispatchEvent(new Event("change",{bubbles:true}));};form.addEventListener("reset",()=>window.setTimeout(restoreAddress,0));form.addEventListener("wpcf7reset",restoreAddress);}
document.addEventListener("click",(event)=>{const button=event.target.closest("[data-bb-ask]");if(!button){return;}
event.preventDefault();opener=button;const name=button.dataset.bbAsk||"";const first=name.split(" ")[0];if(title){title.textContent=first?title.dataset.titleOne.replace("%s",first):title.dataset.titleAny;}
if(choose){const option=Array.from(choose.options).find((o)=>o.value===name);choose.value=option?option.value:choose.options[0].value;const field=choose.closest(".bb-field");if(field){field.hidden=!!option;field.parentElement.classList.toggle("has-one",!!option);}}
const slug=(value)=>value.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");if(button.dataset.bbTopic){const radio=Array.from(popup.querySelectorAll('input[name="topic"]')).find((input)=>slug(input.value)===button.dataset.bbTopic,);if(radio){radio.checked=true;}}
const card=popup.querySelector(".bb-ask__form");if(card){card.dispatchEvent(new CustomEvent("bb-ask:day",{detail:button.dataset.bbWhen||""}));}
popup.showModal();document.documentElement.classList.add("has-bb-sheet");});closable(popup,()=>opener);})();(function(){const popup=document.querySelector(".bb-signup-popup");if(!popup||typeof popup.showModal!=="function"){return;}
let opener=null;document.addEventListener("click",(event)=>{const button=event.target.closest("[data-bb-signup]");if(!button){return;}
event.preventDefault();opener=button;popup.querySelector(".bb-intro__title").textContent=button.dataset.bbSignupTitle||"";popup.querySelector(".bb-signup__when").textContent=button.dataset.bbSignupWhen||"";const date=popup.querySelector('input[name="date"]');if(date){date.value=button.dataset.bbSignup;}
popup.showModal();document.documentElement.classList.add("has-bb-sheet");});closable(popup,()=>opener);})();function closable(popup,opener){popup.querySelector(".bb-ask-popup__close").addEventListener("click",()=>popup.close());popup.addEventListener("click",(event)=>{if(event.target===popup){popup.close();}});popup.addEventListener("close",()=>{document.documentElement.classList.remove("has-bb-sheet");if(opener()){opener().focus();}});}